"use client"

import * as React from "react"
import {
  type ColumnDef,
  type ColumnFiltersState,
  type SortingState,
  type VisibilityState,
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from "@tanstack/react-table"
import { ChevronDown } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { PreviewFrame } from "@/components/preview-frame"
import { PageSizeMenu } from "@/components/policy/page-size-menu"

// shadcn's data table (ui.shadcn.com/docs/components/base/data-table), as the
// demo renders it — the filter box, the Columns menu, the select checkboxes,
// pagination — with the columns handed in. The roll calls and the finance
// totals are two column sets on this one shape.

/** The select column every table leads with, as the demo's does. */
export function selectColumn<T>(): ColumnDef<T> {
  return {
    id: "select",
    header: ({ table }) => (
      <Checkbox
        checked={table.getIsAllPageRowsSelected()}
        indeterminate={table.getIsSomePageRowsSelected() && !table.getIsAllPageRowsSelected()}
        onCheckedChange={(value) => table.toggleAllPageRowsSelected(!!value)}
        aria-label="Select all"
      />
    ),
    cell: ({ row }) => (
      <Checkbox checked={row.getIsSelected()} onCheckedChange={(value) => row.toggleSelected(!!value)} aria-label="Select row" />
    ),
    enableSorting: false,
    enableHiding: false,
  }
}

export function DataTable<T>({
  columns,
  rows,
  filterColumn,
  filterPlaceholder,
  menu,
}: {
  columns: ColumnDef<T>[]
  rows: T[]
  /** The column the filter box searches. */
  filterColumn: string
  filterPlaceholder: string
  /** What sits at the top right: the Columns menu unless another is handed in. */
  menu?: React.ReactNode
}) {
  const [sorting, setSorting] = React.useState<SortingState>([])
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>([])
  const [columnVisibility, setColumnVisibility] = React.useState<VisibilityState>({})
  const [rowSelection, setRowSelection] = React.useState({})

  const table = useReactTable({
    data: rows,
    columns,
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    onColumnVisibilityChange: setColumnVisibility,
    onRowSelectionChange: setRowSelection,
    state: { sorting, columnFilters, columnVisibility, rowSelection },
    initialState: { pagination: { pageSize: 5 } },
  })

  return (
    <PreviewFrame>
            <div className="flex items-center pb-4">
              <Input
                placeholder={filterPlaceholder}
                value={(table.getColumn(filterColumn)?.getFilterValue() as string) ?? ""}
                onChange={(event) => table.getColumn(filterColumn)?.setFilterValue(event.target.value)}
                className="max-w-sm"
              />
              {menu ?? (
              <DropdownMenu>
                <DropdownMenuTrigger
                  render={
                    <Button variant="outline" className="ml-auto">
                      Columns <ChevronDown />
                    </Button>
                  }
                />
                <DropdownMenuContent align="end">
                  {table
                    .getAllColumns()
                    .filter((column) => column.getCanHide())
                    .map((column) => (
                      <DropdownMenuCheckboxItem
                        key={column.id}
                        className="capitalize"
                        checked={column.getIsVisible()}
                        onCheckedChange={(value) => column.toggleVisibility(!!value)}
                      >
                        {column.id}
                      </DropdownMenuCheckboxItem>
                    ))}
                </DropdownMenuContent>
              </DropdownMenu>
              )}
            </div>
            <div className="overflow-hidden rounded-md border">
              <Table>
                <TableHeader>
                  {table.getHeaderGroups().map((headerGroup) => (
                    <TableRow key={headerGroup.id}>
                      {headerGroup.headers.map((header) => (
                        <TableHead key={header.id}>
                          {header.isPlaceholder ? null : flexRender(header.column.columnDef.header, header.getContext())}
                        </TableHead>
                      ))}
                    </TableRow>
                  ))}
                </TableHeader>
                <TableBody>
                  {table.getRowModel().rows?.length ? (
                    table.getRowModel().rows.map((row) => (
                      <TableRow key={row.id} data-state={row.getIsSelected() && "selected"}>
                        {row.getVisibleCells().map((cell) => (
                          <TableCell key={cell.id}>{flexRender(cell.column.columnDef.cell, cell.getContext())}</TableCell>
                        ))}
                      </TableRow>
                    ))
                  ) : (
                    <TableRow>
                      <TableCell colSpan={columns.length} className="h-24 text-center">
                        No results.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </div>
            <div className="flex items-center justify-end space-x-2 pt-4">
              <div className="flex-1">
                <PageSizeMenu
                  size={table.getState().pagination.pageSize}
                  total={table.getFilteredRowModel().rows.length}
                  onChange={(n) => table.setPageSize(n)}
                />
              </div>
              <div className="space-x-2">
                <Button variant="outline" size="sm" onClick={() => table.previousPage()} disabled={!table.getCanPreviousPage()}>
                  Previous
                </Button>
                <Button variant="outline" size="sm" onClick={() => table.nextPage()} disabled={!table.getCanNextPage()}>
                  Next
                </Button>
              </div>
            </div>
    </PreviewFrame>
  )
}

"use client"

import * as React from "react"

import { fmtNumber } from "@/lib/format"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"

// The footer's left side on every block: "Show 5 of 500 rows", a menu that
// sets how many rows a page holds (Brendan, 2026-09-05). Muted on hover, the
// same width as every other menu on the page.
export const PAGE_SIZES = [5, 10, 20, 50, 100]

export function PageSizeMenu({ size, total, onChange }: { size: number; total: number; onChange: (size: number) => void }) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button type="button" className="rounded-md px-2 py-1 text-sm text-muted-foreground transition-colors hover:bg-muted hover:text-foreground" />
        }
      >
        Show {fmtNumber(Math.min(size, total))} of {fmtNumber(total)} {total === 1 ? "row" : "rows"}
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="w-max min-w-44">
        {PAGE_SIZES.map((n) => (
          <DropdownMenuCheckboxItem key={n} className="whitespace-nowrap" checked={n === size} onCheckedChange={() => onChange(n)}>
            Show {n}
          </DropdownMenuCheckboxItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

import * as React from "react"

// shadcn's component-preview frame, class for class — the rounded box the
// docs show a component in — so a block on our pages sits the way one sits
// in theirs, at 32px all round so the content sits centred (Brendan,
// 2026-09-05). The data tables, the committee cards, and the Bills and Votes
// lists all render inside it.
export function PreviewFrame({ children }: { children: React.ReactNode }) {
  return (
    <div data-slot="component-preview" data-not-typeset="true" className="group relative mt-4 mb-12 flex flex-col overflow-hidden rounded-2xl border">
      <div data-slot="preview" dir="ltr">
        <div
          data-align="start"
          data-chromeless="false"
          className="preview relative flex h-auto w-full items-start justify-center p-8 data-[align=center]:items-center data-[align=end]:items-start data-[align=start]:items-start data-[chromeless=true]:h-auto data-[chromeless=true]:p-0 sm:data-[align=end]:items-end"
        >
          <div className="w-full">{children}</div>
        </div>
      </div>
    </div>
  )
}
